// 학습진단 v3.0 원본 xlsx를 TS 모듈로 옮긴다.
//   src/lib/diagnosis-v3/source/score-v3.0.xlsx -> scoreSheets.ts
//   src/lib/diagnosis-v3/source/copy-v3.0.xlsx  -> copyText.ts
// 사용: npm run gen:diagnosis-v3
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildCopyText, extractSheets } from "./lib/diagnosisV3Extract.mjs";

const sourceDir = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "src",
  "lib",
  "diagnosis-v3",
  "source",
);

const HEADER =
  "// Generated by scripts/diagnosis-v3-generate.mjs from the xlsx. Do not edit by hand.\n";

// 한글 외의 비ASCII 글자(가운뎃점, 대시, 화살표, 따옴표 등)는 \\uXXXX로 적는다.
const literal = (value) =>
  JSON.stringify(value).replace(
    /[^\x20-\x7e\u1100-\u11ff\u3130-\u318f\uac00-\ud7a3]/g,
    (ch) => `\\u${ch.charCodeAt(0).toString(16).padStart(4, "0")}`,
  );

const sheetsLiteral = (sheets) =>
  `{\n${Object.entries(sheets)
    .map(
      ([name, rows]) =>
        `${literal(name)}: [\n${rows
          .map((row) => `{ r: ${row.r}, c: ${literal(row.c)} },`)
          .join("\n")}\n],`,
    )
    .join("\n")}\n}`;

const SHEET_TYPES = `export type SheetRow = {
  readonly r: number;
  readonly c: readonly (string | number | null)[];
};

`;

const read = (name) => extractSheets(readFileSync(join(sourceDir, name)));

const score = read("score-v3.0.xlsx");
writeFileSync(
  join(sourceDir, "scoreSheets.ts"),
  `${HEADER}\n${SHEET_TYPES}export const SCORE_SHEETS: Readonly<Record<string, readonly SheetRow[]>> = ${sheetsLiteral(score)};\n`,
);

const copy = read("copy-v3.0.xlsx");
const copyText = buildCopyText(copy);
writeFileSync(
  join(sourceDir, "copyText.ts"),
  `${HEADER}\nimport type { SheetRow } from "./scoreSheets.js";\n\nexport const COPY_TEXT: Readonly<Record<string, string>> = ${literal(copyText)};\n\nexport const COPY_SHEETS: Readonly<Record<string, readonly SheetRow[]>> = ${sheetsLiteral(copy)};\n`,
);

console.log(
  `scoreSheets: ${Object.keys(score).length} sheets, copyText: ${Object.keys(copyText).length} ids, copySheets: ${Object.keys(copy).length} sheets`,
);
